contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public {
        require(caller != address(0));

        address beforeOwner = c.owner();

        bool preReverted;
        if (caller != beforeOwner) {
            // only the owner may call, so expect a revert
            try c.setOwner(newOwner) {
                preReverted = false;
            } catch {
                preReverted = true;
            }
            assert(preReverted && c.owner() == beforeOwner);
            return;
        }

        // caller is the owner: succeed and update
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        if (caller == beforeOwner) {
            assert(ok && c.owner() == newOwner);
        }
    }
}

